<script setup lang="ts">
onMounted(() => {
  const $ = (s: string) => document.querySelector(s) as HTMLElement
  const all = (s: string) => [...document.querySelectorAll(s)] as HTMLElement[]
  const reduce = matchMedia('(prefers-reduced-motion:reduce)').matches
  const progress = $('.scroll-progress')
  const clamp = (v: number) => Math.max(0, Math.min(1, v))
  const onScroll = () => {
    progress.style.transform = `scaleX(${scrollY / Math.max(1, document.documentElement.scrollHeight - innerHeight)})`
    if (reduce) return
    const pr = $('.portal-journey').getBoundingClientRect()
    const pv = clamp((innerHeight - pr.top) / (innerHeight + pr.height))
    $('.portal-torus').style.transform = `rotate(${-24 + pv * 340}deg) scale(${1 + pv * .65})`
    $('.portal-title-wrap').style.transform = `translateY(${100 - pv * 220}px) scale(${.9 + pv * .22})`
    all('.project-chapter').forEach((sec, i) => {
      const r = sec.getBoundingClientRect(), v = clamp((innerHeight - r.top) / (innerHeight + r.height))
      $('#' + sec.id + ' [data-project-visual]').style.transform = `translateY(${115 - 230 * v}px) rotateY(${(i % 2 ? -1 : 1) * (-12 + 24 * v)}deg) rotateX(${5 - 10 * v}deg) scale(${.83 + v * .25})`
      const c = sec.querySelector('[data-project-copy]') as HTMLElement
      c.style.transform = `translateY(${40 - 72 * v}px)`; c.style.opacity = String(.57 + v * .43)
    })
  }
  addEventListener('scroll', onScroll, { passive: true }); onScroll()
  const io = new IntersectionObserver(es => es.forEach(e => { if (e.isIntersecting) { const t = e.target as HTMLElement; t.style.opacity = '1'; t.style.transform = 'translateY(0)'; io.unobserve(t) } }), { threshold: .1 })
  all('[data-reveal]').forEach(el => { if (!reduce) { el.style.transition = 'opacity .9s ease,transform .9s cubic-bezier(.2,.6,.2,1)'; el.style.opacity = '0'; el.style.transform = 'translateY(38px)' } io.observe(el) })
  all('.browser-frame').forEach(el => {
    el.addEventListener('pointermove', (e: PointerEvent) => { const r = el.getBoundingClientRect(); el.style.setProperty('--hover-ry', ((e.clientX - r.left) / r.width - .5) * 4 + 'deg'); el.style.setProperty('--hover-rx', (.5 - (e.clientY - r.top) / r.height) * 4 + 'deg') })
    el.addEventListener('pointerleave', () => { el.style.setProperty('--hover-ry', '0deg'); el.style.setProperty('--hover-rx', '0deg') })
  })
  const dialog = $('#preview-dialog')
  const info: Record<string, string[]> = {
    'nexora': ['NEXORA', 'A modern, creative digital agency website with a futuristic design, smooth animations and a fully responsive layout.'],
    'asa-shop': ['ASA SHOP', 'An e-commerce website with a clean, modern design, built for a smooth shopping experience and high performance.'],
    'computer-store': ['COMPUTER STORE', 'A modern online store for computer and gaming products, with a clean UI, powerful search and a seamless experience.']
  }
  all('[data-modal]').forEach(el => el.addEventListener('click', e => {
    e.preventDefault(); const [n, d] = info[el.dataset.modal!]
    $('#dialog-title').textContent = n; $('#dialog-desc').textContent = d
    dialog.style.display = 'grid'; document.body.style.overflow = 'hidden'
  }))
  const close = () => { dialog.style.display = 'none'; document.body.style.overflow = '' }
  $('#dialog-close').addEventListener('click', close); $('#dialog-back').addEventListener('click', close)
  dialog.addEventListener('click', e => { if (e.target === dialog) close() })
  addEventListener('keydown', e => { if (e.key === 'Escape') close() })
})
</script>

